def backfill_approvals(apps, schema_editor):
    """Record the single approval each already-active contract had (from its
    workflow history). Contracts with one approval keep pre-approving only
    invoices below the two-approver threshold (review SEC-002)."""
    Contract = apps.get_model("operations", "Contract")
    ContractApproval = apps.get_model("operations", "ContractApproval")
    WorkflowEvent = apps.get_model("core", "WorkflowEvent")
    for contract in Contract.objects.exclude(state="draft"):
        events = WorkflowEvent.objects.filter(
            workflow="contract", object_id=str(contract.pk), action="approve"
        ).exclude(actor=None)
        for event in events[:1]:
            ContractApproval.objects.create(
                contract=contract,
                approver_id=event.actor_id,
                amount_cap_cents=contract.amount_cap_cents,
                note=event.note,
                created_at=event.created_at,
            )


# The approvals count joins the terms fixed once a contract is approved.
FREEZE_SQL = """
CREATE OR REPLACE FUNCTION operations_contract_freeze() RETURNS trigger AS $$
BEGIN
  IF OLD.state <> 'draft' AND (
       NEW.vendor_id IS DISTINCT FROM OLD.vendor_id
    OR NEW.amount_cap_cents IS DISTINCT FROM OLD.amount_cap_cents
    OR NEW.schedule IS DISTINCT FROM OLD.schedule
    OR NEW.category_id IS DISTINCT FROM OLD.category_id
    OR NEW.starts_on IS DISTINCT FROM OLD.starts_on
    OR NEW.citation IS DISTINCT FROM OLD.citation
    OR NEW.required_approvals IS DISTINCT FROM OLD.required_approvals
    OR (OLD.ends_on IS NOT NULL AND NEW.ends_on IS DISTINCT FROM OLD.ends_on)
  ) THEN
    RAISE EXCEPTION 'contract % is approved: its terms are fixed', OLD.id
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;
"""

FREEZE_SQL_OLD = FREEZE_SQL.replace(
    "    OR NEW.required_approvals IS DISTINCT FROM OLD.required_approvals\n", ""
)


